/**
 * Corporation Name Reindex - From Existing Killmail Data
 * Version: 2.0 - NO ESI CALLS
 * 
 * Reads corp names directly from existing killmail data in Redis.
 */

const Redis = require('ioredis');

const REDIS_CONFIG = {
    host: 'redis',
    port: 6379,
    db: 0,
    connectTimeout: 10000,
    maxRetriesPerRequest: 3
};

const CORP_NAME_TO_ID_KEY = 'eve:corporation:name_to_id';
const CORP_ID_TO_NAME_KEY = 'eve:corporation:id_to_name';
const CORP_TICKER_TO_ID_KEY = 'eve:corporation:ticker_to_id';
const CORP_ID_TO_TICKER_KEY = 'eve:corporation:id_to_ticker';
const KILLMAIL_DATA_KEY = 'intel:kill:data';

function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

function formatNumber(num) {
    return num.toLocaleString('en-US');
}

let redis;
const stats = {
    startTime: Date.now(),
    killmailsScanned: 0,
    corpsFound: 0,
    indexed: 0,
    skipped: 0
};

try {
    console.log('='.repeat(70));
    console.log('   CORPORATION NAME REINDEX (FROM KILLMAIL DATA)');
    console.log('='.repeat(70));

    redis = new Redis(REDIS_CONFIG);

    await new Promise((resolve, reject) => {
        redis.on('ready', () => {
            console.log('[Redis] ✅ Connected\n');
            resolve();
        });
        redis.on('error', (err) => {
            console.error('[Redis] ❌ Connection failed:', err.message);
            reject(err);
        });
    });

    console.log('[Scan] Scanning killmail data for corporation names...');

    // Collect all unique corp names from killmail data
    const corpMap = new Map(); // corpId -> { name, ticker }
    let cursor = '0';
    let batchNum = 0;

    do {
        // Scan killmail hash in batches
        const [nextCursor, killmailIds] = await redis.hscan(
            KILLMAIL_DATA_KEY,
            cursor,
            'COUNT', 500
        );

        cursor = nextCursor;

        // Fetch killmail data for this batch
        if (killmailIds.length > 0) {
            // hscan returns [field, value, field, value, ...]
            // So we take every other item starting from index 1 (the values)
            const killmailJsons = [];
            for (let i = 1; i < killmailIds.length; i += 2) {
                killmailJsons.push(killmailIds[i]);
            }

            batchNum++;
            stats.killmailsScanned += killmailJsons.length;

            console.log(`[Batch ${batchNum}] Processing ${killmailJsons.length} killmails...`);

            // Extract corp info from each killmail
            for (const kmJson of killmailJsons) {
                try {
                    const km = JSON.parse(kmJson);

                    // Victim corp
                    if (km.victim?.corporation_id && km.victim?.corporation_name) {
                        const corpId = String(km.victim.corporation_id);
                        const name = km.victim.corporation_name;

                        if (name && name !== 'Unknown Corp' && !name.startsWith('Corp (') && !name.startsWith('RETRY:')) {
                            if (!corpMap.has(corpId)) {
                                corpMap.set(corpId, { name, ticker: null });
                            }
                        }
                    }

                    // Attacker corps
                    if (km.attackers && Array.isArray(km.attackers)) {
                        for (const attacker of km.attackers) {
                            if (attacker.corporation_id && attacker.corporation_name) {
                                const corpId = String(attacker.corporation_id);
                                const name = attacker.corporation_name;

                                if (name && name !== 'Unknown Corp' && !name.startsWith('Corp (') && !name.startsWith('RETRY:')) {
                                    if (!corpMap.has(corpId)) {
                                        corpMap.set(corpId, { name, ticker: null });
                                    }
                                }
                            }
                        }
                    }
                } catch (e) {
                    // Skip invalid JSON
                }
            }

            console.log(`  Found ${formatNumber(corpMap.size)} unique corporations so far`);

            // Small delay to avoid overwhelming Redis
            if (cursor !== '0') {
                await sleep(100);
            }
        }
    } while (cursor !== '0');

    stats.corpsFound = corpMap.size;

    console.log(`\n[Index] Indexing ${formatNumber(corpMap.size)} corporations into Redis...`);

    if (corpMap.size === 0) {
        return [{ json: {
            success: true,
            message: 'No corporations found in killmail data',
            stats
        } }];
    }

    // Index all corps in Redis
    const indexPipeline = redis.pipeline();

    for (const [corpId, data] of corpMap.entries()) {
        const nameLower = data.name.toLowerCase();

        // Store bidirectional name mappings
        indexPipeline.hset(CORP_ID_TO_NAME_KEY, corpId, data.name);
        indexPipeline.hset(CORP_NAME_TO_ID_KEY, nameLower, corpId);

        stats.indexed++;
    }

    await indexPipeline.exec();

    const totalTime = Math.floor((Date.now() - stats.startTime) / 1000);

    console.log('\n='.repeat(70));
    console.log('                     FINAL REPORT');
    console.log('='.repeat(70));
    console.log(`\nKillmails Scanned:            ${formatNumber(stats.killmailsScanned)}`);
    console.log(`Unique Corporations Found:    ${formatNumber(stats.corpsFound)}`);
    console.log(`Successfully Indexed:         ${formatNumber(stats.indexed)} ✅`);
    console.log(`\nTotal Time:                   ${totalTime} seconds`);
    console.log(`Average Rate:                 ${(stats.indexed / totalTime).toFixed(1)} corps/second`);
    console.log('='.repeat(70));

    return [{ json: {
        success: true,
        stats: {
            killmailsScanned: stats.killmailsScanned,
            corpsFound: stats.corpsFound,
            indexed: stats.indexed,
            durationSeconds: totalTime
        }
    } }];

} catch (error) {
    console.error('\n❌ FATAL ERROR:', error.message);
    console.error(error.stack);

    return [{ json: {
        success: false,
        error: error.message,
        stats
    } }];
} finally {
    if (redis) {
        await redis.quit();
        console.log('\n[Redis] Connection closed');
    }
}
